1	/**
2	 * Standalone CLI entrypoint that drives the same `TelemetryService` +
3	 * reporter stack used by the MCP server.
4	 *
5	 * Supports multiple subcommands. The first positional argument selects
6	 * the subcommand; if it is omitted (i.e. the first argument starts with
7	 * `--`) we default to `send` for backward compatibility.
8	 *
9	 * Subcommands:
10	 *   send            Send a single telemetry event described by --json.
11	 *   session-begin   Mark the beginning of a CLI session. Emits a fixed
12	 *                   `modernization/session/begin` event (per detected
13	 *                   module under --workspacePath).
14	 *
15	 * Global flags (apply to every subcommand):
16	 *   --stdio               Print events to stdout as single-line JSON
17	 *                         instead of sending to Application Insights.
18	 *   --disableTelemetry    Forwarded to Settings; suppresses sends.
19	 *   --callerId <id>       Name of the IDE plugin / extension invoking the
20	 *                         CLI. Examples: `vscode-extension`,
21	 *                         `intellij-plugin`.
22	 *   --callerType <type>   Kind of IDE host. Examples:
23	 *                         `vscode-extension`, `intellij-plugin`.
24	 *   --callerVersion <v>   Version of that plugin / extension.
25	 *   --callerSessionId <id>
26	 *                         IDE-level session id (e.g.
27	 *                         `vscode.env.sessionId`, IntelliJ session
28	 *                         UUID). Surfaced verbatim on every event as
29	 *                         the `callerSessionId` telemetry dimension.
30	 *                         Back-compat field; NOT promoted to
31	 *                         AppInsights operation tags.
32	 *   --sessionId <id>      Agent session id from the surrounding hook /
33	 *                         tool invocation (e.g. Claude Code or GitHub
34	 *                         Copilot CLI hook stdin `session_id`).
35	 *                         Injected as the `correlationId` property,
36	 *                         which the AppInsights pipeline promotes to
37	 *                         the `operation_ParentId` tag so events link
38	 *                         back to the parent agent operation.
39	 *                         Independent of `--callerSessionId`; neither
40	 *                         flag falls back to the other.
41	 *   --workspacePath <p>   Path scanned for application modules. Used
42	 *                         by `send --module-level` to fan a payload
43	 *                         out per detected module, and by
44	 *                         `session-begin` (which always fans out per
45	 *                         module). Defaults to the current working
46	 *                         directory.
47	 *
48	 *   Any other `--key value` pair becomes a fixed string property merged
49	 *   into every event for this run. CLI-provided properties take
50	 *   precedence over those embedded inside --json.
51	 *
52	 * Subcommand-specific flags:
53	 *   send: --json <jsonString>   Required. Either a single event object
54	 *           or an array of event objects. Each event has shape:
55	 *           { "eventName": string, "properties"?: {...}, "measurements"?: {...} }
56	 *           Arrays are sent in order, fail-fast: a bad/failed event
57	 *           aborts the run with exit code 1 and earlier events are NOT
58	 *           rolled back.
59	 *
60	 *   send: --module-level
61	 *           When set, detect application modules in --workspacePath
62	 *           and emit each payload once per detected module, merging
63	 *           that module's app-metadata fields (hashedAppId,
64	 *           javaVersion, buildTool, ...) into the event's properties.
65	 *           If no modules are detected, a single event is still
66	 *           emitted with empty app fields. Without --module-level the
67	 *           event is sent verbatim.
68	 *
69	 *   session-begin: --task <task>   Required. Identifies the high-level
70	 *           task the session is working on. Any non-empty string;
71	 *           surfaced on emitted events as the `sessionTask` property
72	 *           so downstream events can be correlated by task.
73	 */
74	
75	import 'reflect-metadata';
76	
77	import { container } from 'tsyringe';
78	
79	import { initContainer } from '../ioc';
80	import { Settings } from '../settings';
81	import { buildAppMetadataParser } from '../telemetry/appMetadata';
82	import { emptyApp, withApp } from '../telemetry/event';
83	import {
84	    ApplicationInsightsTelemetryReporter,
85	    ITelemetryReporter,
86	    ITelemetryService,
87	    McpPropertyMap,
88	    StdoutTelemetryReporter,
89	} from '../telemetry/telemetry';
90	import { Beans } from '../types';
91	import { parseArgs, ParsedArgs } from '../utils';
92	
93	const SUBCOMMANDS = ['send', 'session-begin'] as const;
94	type Subcommand = (typeof SUBCOMMANDS)[number];
95	
96	// Flags that should NOT be merged into the event's properties bag.
97	// `json`, `task`, and `module-level` are consumed by specific
98	// subcommands; the rest are consumed by Settings, this dispatcher,
99	// or shared across subcommands (workspacePath).
100	const RESERVED_ARG_KEYS = new Set([
101	    'json',
102	    'task',
103	    'module-level',
104	    'workspacePath',
105	    'stdio',
106	    'disableTelemetry',
107	    'callerId',
108	    'callerType',
109	    'callerVersion',
110	    'callerSessionId',
111	    'sessionId',
112	]);
113	
114	interface TelemetryPayload {
115	    eventName: string;
116	    properties?: Record<string, unknown>;
117	    measurements?: Record<string, number>;
118	}
119	
120	interface CliContext {
121	    subcommand: Subcommand;
122	    parsedArgs: ParsedArgs;
123	    /** Property bag from non-reserved `--key value` flags (CLI overrides). */
124	    globalProperties: Record<string, string>;
125	    settings: Settings;
126	    telemetryService: ITelemetryService;
127	    useStdio: boolean;
128	    /** Workspace root scanned for application modules; defaults to process.cwd(). */
129	    workspacePath: string;
130	}
131	
132	function getSubcommand(): { subcommand: Subcommand; rest: string[] } {
133	    const rawArgs = process.argv.slice(2);
134	    const first = rawArgs[0];
135	    if (!first || first.startsWith('--')) {
136	        // Backward compatibility: `node telemetrySender.js --json ...`
137	        // is equivalent to `... send --json ...`.
138	        return { subcommand: 'send', rest: rawArgs };
139	    }
140	    if (!(SUBCOMMANDS as readonly string[]).includes(first)) {
141	        throw new Error(`Unknown subcommand '${first}'. Supported: ${SUBCOMMANDS.join(', ')}.`);
142	    }
143	    return { subcommand: first as Subcommand, rest: rawArgs.slice(1) };
144	}
145	
146	function validatePayload(parsed: unknown, indexLabel: string): TelemetryPayload {
147	    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
148	        throw new Error(`--json ${indexLabel} must be a JSON object.`);
149	    }
150	    const payload = parsed as Partial<TelemetryPayload>;
151	    if (typeof payload.eventName !== 'string' || payload.eventName.length === 0) {
152	        throw new Error(`--json ${indexLabel} must contain a non-empty "eventName" string.`);
153	    }
154	    if (
155	        payload.properties !== undefined &&
156	        (typeof payload.properties !== 'object' || payload.properties === null)
157	    ) {
158	        throw new Error(`--json ${indexLabel} "properties" must be an object when provided.`);
159	    }
160	    if (
161	        payload.measurements !== undefined &&
162	        (typeof payload.measurements !== 'object' || payload.measurements === null)
163	    ) {
164	        throw new Error(`--json ${indexLabel} "measurements" must be an object when provided.`);
165	    }
166	    return {
167	        eventName: payload.eventName,
168	        properties: (payload.properties as Record<string, unknown>) ?? {},
169	        measurements: (payload.measurements as Record<string, number>) ?? {},
170	    };
171	}
172	
173	function parsePayloads(raw: string | undefined): TelemetryPayload[] {
174	    if (!raw) {
175	        throw new Error(
176	            '--json <jsonString> is required and must contain a payload object or array.',
177	        );
178	    }
179	    let parsed: unknown;
180	    try {
181	        parsed = JSON.parse(raw);
182	    } catch (error) {
183	        throw new Error(
184	            `Failed to parse --json value as JSON: ${
185	                error instanceof Error ? error.message : String(error)
186	            }`,
187	        );
188	    }
189	    if (Array.isArray(parsed)) {
190	        if (parsed.length === 0) {
191	            throw new Error('--json array must contain at least one event.');
192	        }
193	        return parsed.map((item, i) => validatePayload(item, `array[${i}]`));
194	    }
195	    return [validatePayload(parsed, 'payload')];
196	}
197	
198	function stringifyProps(props: Record<string, unknown>): Record<string, string> {
199	    const result: Record<string, string> = {};
200	    for (const [k, v] of Object.entries(props)) {
201	        if (v === undefined || v === null) {
202	            continue;
203	        }
204	        result[k] = typeof v === 'string' ? v : JSON.stringify(v);
205	    }
206	    return result;
207	}
208	
209	async function sendEvent(
210	    ctx: CliContext,
211	    eventName: string,
212	    extraProperties: Record<string, string> = {},
213	    measurements: Record<string, number> = {},
214	): Promise<void> {
215	    const properties: Record<string, string> = {
216	        ...extraProperties,
217	        ...ctx.globalProperties, // CLI globals always win
218	    };
219	    await ctx.telemetryService.sendTelemetryEvent(
220	        eventName as keyof McpPropertyMap,
221	        properties as McpPropertyMap[keyof McpPropertyMap]['properties'],
222	        measurements as McpPropertyMap[keyof McpPropertyMap]['measurements'],
223	    );
224	}
225	
226	// ---------------------------------------------------------------------------
227	// Subcommand: send
228	// ---------------------------------------------------------------------------
229	/**
230	 * Detects application modules under `ctx.workspacePath` and returns one
231	 * app-metadata property bag per module. If no modules are detected, a
232	 * single bag with empty app fields is returned so the event is still
233	 * emitted exactly once.
234	 */
235	function detectModuleAppBags(ctx: CliContext): Record<string, unknown>[] {
236	    const metadatas = buildAppMetadataParser(ctx.workspacePath).findAppMetadatas();
237	    if (metadatas.length === 0) {
238	        return [emptyApp() as unknown as Record<string, unknown>];
239	    }
240	    return metadatas.map((m) => withApp(m) as unknown as Record<string, unknown>);
241	}
242	
243	/**
244	 * Returns the list of app-metadata bags to fan `send` out across.
245	 * Without `--module-level` the list is `[{}]` (single event, no app
246	 * fields). With `--module-level`, delegates to `detectModuleAppBags`.
247	 */
248	function resolveSendAppBags(ctx: CliContext): Record<string, unknown>[] {
249	    if (ctx.parsedArgs['module-level'] === undefined) {
250	        return [{}];
251	    }
252	    return detectModuleAppBags(ctx);
253	}
254	
255	async function runSend(ctx: CliContext): Promise<void> {
256	    const payloads = parsePayloads(ctx.parsedArgs['json']);
257	    const appBags = resolveSendAppBags(ctx);
258	    // Fail-fast: any throw aborts the loop; previously sent events are
259	    // not rolled back. Caller can re-run with the remaining slice.
260	    let sentCount = 0;
261	    for (const payload of payloads) {
262	        const baseProps = stringifyProps(payload.properties ?? {});
263	        for (const appBag of appBags) {
264	            await sendEvent(
265	                ctx,
266	                payload.eventName,
267	                { ...baseProps, ...stringifyProps(appBag) },
268	                payload.measurements ?? {},
269	            );
270	            sentCount++;
271	        }
272	    }
273	    if (!ctx.useStdio) {
274	        if (sentCount === 1) {
275	            process.stdout.write(`Sent telemetry event '${payloads[0].eventName}'.\n`);
276	        } else {
277	            process.stdout.write(`Sent ${sentCount} telemetry events.\n`);
278	        }
279	    }
280	}
281	
282	// ---------------------------------------------------------------------------
283	// Subcommand: session-begin
284	//
285	// Emits a single `cli/session/begin` event tagged with:
286	//   - callerSessionId  (from --callerSessionId, or generated UUID)
287	//   - sessionTask      (from --task; required, allow-listed)
288	//   - startedAt        (ISO timestamp)
289	//
290	// callerSessionId flows through Settings so the standard
291	// static-properties pipeline surfaces it on every event. sessionTask
292	// is attached as an extra property on the begin event itself.
293	//
294	// TODO: layer the additional fixed events / operations that should run
295	// at session start once the spec is finalized.
296	// ---------------------------------------------------------------------------
297	const SESSION_BEGIN_EVENT_NAME = 'modernization/session/begin';
298	
299	function parseSessionTask(raw: string | undefined): string {
300	    if (!raw) {
301	        throw new Error(`--task <task> is required for 'session-begin'.`);
302	    }
303	    return raw;
304	}
305	
306	async function runSessionBegin(ctx: CliContext): Promise<void> {
307	    const sessionTask = parseSessionTask(ctx.parsedArgs['task']);
308	    const startedAt = new Date().toISOString();
309	
310	    // session-begin always fans out per detected module under
311	    // --workspacePath so every (session, module) pair gets a begin
312	    // marker. Empty workspaces still emit exactly one event via the
313	    // emptyApp() fallback in detectModuleAppBags.
314	    const appBags = detectModuleAppBags(ctx);
315	    for (const appBag of appBags) {
316	        await sendEvent(ctx, SESSION_BEGIN_EVENT_NAME, {
317	            ...stringifyProps(appBag),
318	            sessionTask,
319	            startedAt,
320	        });
321	    }
322	
323	    // In --stdio mode the event JSON is the only stdout output; otherwise
324	    // print a short human-readable summary.
325	    if (!ctx.useStdio) {
326	        const suffix = appBags.length > 1 ? ` across ${appBags.length} modules` : '';
327	        process.stdout.write(`Started ${sessionTask} session${suffix}.\n`);
328	    }
329	}
330	
331	// ---------------------------------------------------------------------------
332	// Dispatch
333	// ---------------------------------------------------------------------------
334	async function main(): Promise<void> {
335	    const { subcommand } = getSubcommand();
336	    const parsedArgs = parseArgs();
337	
338	    const globalProperties: Record<string, string> = {};
339	    for (const [key, value] of Object.entries(parsedArgs)) {
340	        if (RESERVED_ARG_KEYS.has(key)) {
341	            continue;
342	        }
343	        globalProperties[key] = value;
344	    }
345	
346	    // Reuse the same Settings + DI graph the MCP server uses so static
347	    // properties (serverName, callerId, deviceId, machineId, ...) are
348	    // appended exactly like production telemetry.
349	    const settings = Settings.fromEnv();
350	    settings.loggerType = 'console';
351	    // Clear serveFrom so CLI-emitted events are not mis-attributed to the
352	    // mcp-server process. Callers can still tag origin via --callerId /
353	    // --callerType or arbitrary --key value globals.
354	    settings.serveFrom = '';
355	
356	    // Session-id wiring (independent; neither one falls back to the other):
357	    //   --callerSessionId  -> Settings.callerSessionId (telemetry static
358	    //                         property `callerSessionId`; back-compat
359	    //                         dimension, NOT promoted to AppInsights
360	    //                         operation tags).
361	    //   --sessionId        -> `correlationId` global property, promoted
362	    //                         to AppInsights `operation_ParentId` tag.
363	    // Both flags are opt-in; no auto-generation, no cross-fallback.
364	    if (parsedArgs['callerSessionId']) {
365	        settings.callerSessionId = parsedArgs['callerSessionId'];
366	    }
367	    if (parsedArgs['sessionId']) {
368	        globalProperties['correlationId'] = parsedArgs['sessionId'];
369	    }
370	
371	    initContainer(settings);
372	
373	    // Swap reporter for stdout BEFORE resolving TelemetryService so the
374	    // service still appends configured static properties.
375	    const useStdio = parsedArgs['stdio'] !== undefined;
376	    if (useStdio) {
377	        container.register<ITelemetryReporter>(Beans.TelemetryReporter, {
378	            useValue: new StdoutTelemetryReporter(),
379	        });
380	    }
381	
382	    const telemetryService = container.resolve<ITelemetryService>(Beans.TelemetryService);
383	    const ctx: CliContext = {
384	        subcommand,
385	        parsedArgs,
386	        globalProperties,
387	        settings,
388	        telemetryService,
389	        useStdio,
390	        workspacePath: parsedArgs['workspacePath'] || process.cwd(),
391	    };
392	
393	    switch (subcommand) {
394	        case 'send':
395	            await runSend(ctx);
396	            break;
397	        case 'session-begin':
398	            await runSessionBegin(ctx);
399	            break;
400	        default: {
401	            // Exhaustiveness check.
402	            const _exhaustive: never = subcommand;
403	            throw new Error(`Unhandled subcommand: ${_exhaustive as string}`);
404	        }
405	    }
406	
407	    // Ensure buffered events leave the process before exit.
408	    if (!useStdio && container.isRegistered(Beans.TelemetryReporter)) {
409	        const reporter = container.resolve(Beans.TelemetryReporter);
410	        if (reporter instanceof ApplicationInsightsTelemetryReporter) {
411	            await reporter.flush();
412	        }
413	    }
414	}
415	
416	main()
417	    .then(() => process.exit(0))
418	    .catch((error: Error) => {
419	        process.stderr.write(`Failed: ${error.message}\n`);
420	        process.exit(1);
421	    });
422

