/**
 * Standalone CLI entrypoint that drives the same `TelemetryService` +
 * reporter stack used by the MCP server.
 *
 * Supports multiple subcommands. The first positional argument selects
 * the subcommand; if it is omitted (i.e. the first argument starts with
 * `--`) we default to `send` for backward compatibility.
 *
 * Subcommands:
 *   send            Send a single telemetry event described by --json.
 *   session-begin   Mark the beginning of a CLI session. Emits a fixed
 *                   `modernization/session/begin` event (per detected
 *                   module under --workspacePath).
 *
 * Global flags (apply to every subcommand):
 *   --stdio               Print events to stdout as single-line JSON
 *                         instead of sending to Application Insights.
 *   --disableTelemetry    Forwarded to Settings; suppresses sends.
 *   --callerId <id>       Name of the IDE plugin / extension invoking the
 *                         CLI. Examples: `vscode-extension`,
 *                         `intellij-plugin`.
 *   --callerType <type>   Kind of IDE host. Examples:
 *                         `vscode-extension`, `intellij-plugin`.
 *   --callerVersion <v>   Version of that plugin / extension.
 *   --callerSessionId <id>
 *                         IDE-level session id (e.g.
 *                         `vscode.env.sessionId`, IntelliJ session
 *                         UUID). Surfaced verbatim on every event as
 *                         the `callerSessionId` telemetry dimension.
 *                         Back-compat field; NOT promoted to
 *                         AppInsights operation tags.
 *   --sessionId <id>      Agent session id from the surrounding hook /
 *                         tool invocation (e.g. Claude Code or GitHub
 *                         Copilot CLI hook stdin `session_id`).
 *                         Injected as the `correlationId` property,
 *                         which the AppInsights pipeline promotes to
 *                         the `operation_ParentId` tag so events link
 *                         back to the parent agent operation.
 *                         Independent of `--callerSessionId`; neither
 *                         flag falls back to the other.
 *   --workspacePath <p>   Path scanned for application modules. Used
 *                         by `send --module-level` to fan a payload
 *                         out per detected module, and by
 *                         `session-begin` (which always fans out per
 *                         module). Defaults to the current working
 *                         directory.
 *
 *   Any other `--key value` pair becomes a fixed string property merged
 *   into every event for this run. CLI-provided properties take
 *   precedence over those embedded inside --json.
 *
 * Subcommand-specific flags:
 *   send: --json <jsonString>   Required. Either a single event object
 *           or an array of event objects. Each event has shape:
 *           { "eventName": string, "properties"?: {...}, "measurements"?: {...} }
 *           Arrays are sent in order, fail-fast: a bad/failed event
 *           aborts the run with exit code 1 and earlier events are NOT
 *           rolled back.
 *
 *   send: --module-level
 *           When set, detect application modules in --workspacePath
 *           and emit each payload once per detected module, merging
 *           that module's app-metadata fields (hashedAppId,
 *           javaVersion, buildTool, ...) into the event's properties.
 *           If no modules are detected, a single event is still
 *           emitted with empty app fields. Without --module-level the
 *           event is sent verbatim.
 *
 *   session-begin: --task <task>   Required. Identifies the high-level
 *           task the session is working on. Any non-empty string;
 *           surfaced on emitted events as the `sessionTask` property
 *           so downstream events can be correlated by task.
 */

import 'reflect-metadata';

import { container } from 'tsyringe';

import { initContainer } from '../ioc';
import { Settings } from '../settings';
import { buildAppMetadataParser } from '../telemetry/appMetadata';
import { emptyApp, withApp } from '../telemetry/event';
import {
    ApplicationInsightsTelemetryReporter,
    ITelemetryReporter,
    ITelemetryService,
    McpPropertyMap,
    StdoutTelemetryReporter,
} from '../telemetry/telemetry';
import { Beans } from '../types';
import { parseArgs, ParsedArgs } from '../utils';

const SUBCOMMANDS = ['send', 'session-begin'] as const;
type Subcommand = (typeof SUBCOMMANDS)[number];

// Flags that should NOT be merged into the event's properties bag.
// `json`, `task`, and `module-level` are consumed by specific
// subcommands; the rest are consumed by Settings, this dispatcher,
// or shared across subcommands (workspacePath).
const RESERVED_ARG_KEYS = new Set([
    'json',
    'task',
    'module-level',
    'workspacePath',
    'stdio',
    'disableTelemetry',
    'callerId',
    'callerType',
    'callerVersion',
    'callerSessionId',
    'sessionId',
]);

interface TelemetryPayload {
    eventName: string;
    properties?: Record<string, unknown>;
    measurements?: Record<string, number>;
}

interface CliContext {
    subcommand: Subcommand;
    parsedArgs: ParsedArgs;
    /** Property bag from non-reserved `--key value` flags (CLI overrides). */
    globalProperties: Record<string, string>;
    settings: Settings;
    telemetryService: ITelemetryService;
    useStdio: boolean;
    /** Workspace root scanned for application modules; defaults to process.cwd(). */
    workspacePath: string;
}

function getSubcommand(): { subcommand: Subcommand; rest: string[] } {
    const rawArgs = process.argv.slice(2);
    const first = rawArgs[0];
    if (!first || first.startsWith('--')) {
        // Backward compatibility: `node telemetrySender.js --json ...`
        // is equivalent to `... send --json ...`.
        return { subcommand: 'send', rest: rawArgs };
    }
    if (!(SUBCOMMANDS as readonly string[]).includes(first)) {
        throw new Error(`Unknown subcommand '${first}'. Supported: ${SUBCOMMANDS.join(', ')}.`);
    }
    return { subcommand: first as Subcommand, rest: rawArgs.slice(1) };
}

function validatePayload(parsed: unknown, indexLabel: string): TelemetryPayload {
    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
        throw new Error(`--json ${indexLabel} must be a JSON object.`);
    }
    const payload = parsed as Partial<TelemetryPayload>;
    if (typeof payload.eventName !== 'string' || payload.eventName.length === 0) {
        throw new Error(`--json ${indexLabel} must contain a non-empty "eventName" string.`);
    }
    if (
        payload.properties !== undefined &&
        (typeof payload.properties !== 'object' || payload.properties === null)
    ) {
        throw new Error(`--json ${indexLabel} "properties" must be an object when provided.`);
    }
    if (
        payload.measurements !== undefined &&
        (typeof payload.measurements !== 'object' || payload.measurements === null)
    ) {
        throw new Error(`--json ${indexLabel} "measurements" must be an object when provided.`);
    }
    return {
        eventName: payload.eventName,
        properties: (payload.properties as Record<string, unknown>) ?? {},
        measurements: (payload.measurements as Record<string, number>) ?? {},
    };
}

function parsePayloads(raw: string | undefined): TelemetryPayload[] {
    if (!raw) {
        throw new Error(
            '--json <jsonString> is required and must contain a payload object or array.',
        );
    }
    let parsed: unknown;
    try {
        parsed = JSON.parse(raw);
    } catch (error) {
        throw new Error(
            `Failed to parse --json value as JSON: ${
                error instanceof Error ? error.message : String(error)
            }`,
        );
    }
    if (Array.isArray(parsed)) {
        if (parsed.length === 0) {
            throw new Error('--json array must contain at least one event.');
        }
        return parsed.map((item, i) => validatePayload(item, `array[${i}]`));
    }
    return [validatePayload(parsed, 'payload')];
}

function stringifyProps(props: Record<string, unknown>): Record<string, string> {
    const result: Record<string, string> = {};
    for (const [k, v] of Object.entries(props)) {
        if (v === undefined || v === null) {
            continue;
        }
        result[k] = typeof v === 'string' ? v : JSON.stringify(v);
    }
    return result;
}

async function sendEvent(
    ctx: CliContext,
    eventName: string,
    extraProperties: Record<string, string> = {},
    measurements: Record<string, number> = {},
): Promise<void> {
    const properties: Record<string, string> = {
        ...extraProperties,
        ...ctx.globalProperties, // CLI globals always win
    };
    await ctx.telemetryService.sendTelemetryEvent(
        eventName as keyof McpPropertyMap,
        properties as McpPropertyMap[keyof McpPropertyMap]['properties'],
        measurements as McpPropertyMap[keyof McpPropertyMap]['measurements'],
    );
}

// ---------------------------------------------------------------------------
// Subcommand: send
// ---------------------------------------------------------------------------
/**
 * Detects application modules under `ctx.workspacePath` and returns one
 * app-metadata property bag per module. If no modules are detected, a
 * single bag with empty app fields is returned so the event is still
 * emitted exactly once.
 */
function detectModuleAppBags(ctx: CliContext): Record<string, unknown>[] {
    const metadatas = buildAppMetadataParser(ctx.workspacePath).findAppMetadatas();
    if (metadatas.length === 0) {
        return [emptyApp() as unknown as Record<string, unknown>];
    }
    return metadatas.map((m) => withApp(m) as unknown as Record<string, unknown>);
}

/**
 * Returns the list of app-metadata bags to fan `send` out across.
 * Without `--module-level` the list is `[{}]` (single event, no app
 * fields). With `--module-level`, delegates to `detectModuleAppBags`.
 */
function resolveSendAppBags(ctx: CliContext): Record<string, unknown>[] {
    if (ctx.parsedArgs['module-level'] === undefined) {
        return [{}];
    }
    return detectModuleAppBags(ctx);
}

async function runSend(ctx: CliContext): Promise<void> {
    const payloads = parsePayloads(ctx.parsedArgs['json']);
    const appBags = resolveSendAppBags(ctx);
    // Fail-fast: any throw aborts the loop; previously sent events are
    // not rolled back. Caller can re-run with the remaining slice.
    let sentCount = 0;
    for (const payload of payloads) {
        const baseProps = stringifyProps(payload.properties ?? {});
        for (const appBag of appBags) {
            await sendEvent(
                ctx,
                payload.eventName,
                { ...baseProps, ...stringifyProps(appBag) },
                payload.measurements ?? {},
            );
            sentCount++;
        }
    }
    if (!ctx.useStdio) {
        if (sentCount === 1) {
            process.stdout.write(`Sent telemetry event '${payloads[0].eventName}'.\n`);
        } else {
            process.stdout.write(`Sent ${sentCount} telemetry events.\n`);
        }
    }
}

// ---------------------------------------------------------------------------
// Subcommand: session-begin
//
// Emits a single `cli/session/begin` event tagged with:
//   - callerSessionId  (from --callerSessionId, or generated UUID)
//   - sessionTask      (from --task; required, allow-listed)
//   - startedAt        (ISO timestamp)
//
// callerSessionId flows through Settings so the standard
// static-properties pipeline surfaces it on every event. sessionTask
// is attached as an extra property on the begin event itself.
//
// TODO: layer the additional fixed events / operations that should run
// at session start once the spec is finalized.
// ---------------------------------------------------------------------------
const SESSION_BEGIN_EVENT_NAME = 'modernization/session/begin';

function parseSessionTask(raw: string | undefined): string {
    if (!raw) {
        throw new Error(`--task <task> is required for 'session-begin'.`);
    }
    return raw;
}

async function runSessionBegin(ctx: CliContext): Promise<void> {
    const sessionTask = parseSessionTask(ctx.parsedArgs['task']);
    const startedAt = new Date().toISOString();

    // session-begin always fans out per detected module under
    // --workspacePath so every (session, module) pair gets a begin
    // marker. Empty workspaces still emit exactly one event via the
    // emptyApp() fallback in detectModuleAppBags.
    const appBags = detectModuleAppBags(ctx);
    for (const appBag of appBags) {
        await sendEvent(ctx, SESSION_BEGIN_EVENT_NAME, {
            ...stringifyProps(appBag),
            sessionTask,
            startedAt,
        });
    }

    // In --stdio mode the event JSON is the only stdout output; otherwise
    // print a short human-readable summary.
    if (!ctx.useStdio) {
        const suffix = appBags.length > 1 ? ` across ${appBags.length} modules` : '';
        process.stdout.write(`Started ${sessionTask} session${suffix}.\n`);
    }
}

// ---------------------------------------------------------------------------
// Dispatch
// ---------------------------------------------------------------------------
async function main(): Promise<void> {
    const { subcommand } = getSubcommand();
    const parsedArgs = parseArgs();

    const globalProperties: Record<string, string> = {};
    for (const [key, value] of Object.entries(parsedArgs)) {
        if (RESERVED_ARG_KEYS.has(key)) {
            continue;
        }
        globalProperties[key] = value;
    }

    // Reuse the same Settings + DI graph the MCP server uses so static
    // properties (serverName, callerId, deviceId, machineId, ...) are
    // appended exactly like production telemetry.
    const settings = Settings.fromEnv();
    settings.loggerType = 'console';
    // Clear serveFrom so CLI-emitted events are not mis-attributed to the
    // mcp-server process. Callers can still tag origin via --callerId /
    // --callerType or arbitrary --key value globals.
    settings.serveFrom = '';

    // Session-id wiring (independent; neither one falls back to the other):
    //   --callerSessionId  -> Settings.callerSessionId (telemetry static
    //                         property `callerSessionId`; back-compat
    //                         dimension, NOT promoted to AppInsights
    //                         operation tags).
    //   --sessionId        -> `correlationId` global property, promoted
    //                         to AppInsights `operation_ParentId` tag.
    // Both flags are opt-in; no auto-generation, no cross-fallback.
    if (parsedArgs['callerSessionId']) {
        settings.callerSessionId = parsedArgs['callerSessionId'];
    }
    if (parsedArgs['sessionId']) {
        globalProperties['correlationId'] = parsedArgs['sessionId'];
    }

    initContainer(settings);

    // Swap reporter for stdout BEFORE resolving TelemetryService so the
    // service still appends configured static properties.
    const useStdio = parsedArgs['stdio'] !== undefined;
    if (useStdio) {
        container.register<ITelemetryReporter>(Beans.TelemetryReporter, {
            useValue: new StdoutTelemetryReporter(),
        });
    }

    const telemetryService = container.resolve<ITelemetryService>(Beans.TelemetryService);
    const ctx: CliContext = {
        subcommand,
        parsedArgs,
        globalProperties,
        settings,
        telemetryService,
        useStdio,
        workspacePath: parsedArgs['workspacePath'] || process.cwd(),
    };

    switch (subcommand) {
        case 'send':
            await runSend(ctx);
            break;
        case 'session-begin':
            await runSessionBegin(ctx);
            break;
        default: {
            // Exhaustiveness check.
            const _exhaustive: never = subcommand;
            throw new Error(`Unhandled subcommand: ${_exhaustive as string}`);
        }
    }

    // Ensure buffered events leave the process before exit.
    if (!useStdio && container.isRegistered(Beans.TelemetryReporter)) {
        const reporter = container.resolve(Beans.TelemetryReporter);
        if (reporter instanceof ApplicationInsightsTelemetryReporter) {
            await reporter.flush();
        }
    }
}

main()
    .then(() => process.exit(0))
    .catch((error: Error) => {
        process.stderr.write(`Failed: ${error.message}\n`);
        process.exit(1);
    });

