// ---------------------------------------------------------------------------
// DEBUG main: capture hook stdin so we can see exactly what the host
// (VS Code chat / Copilot CLI) writes to the hook process.
//
// Usage from a hook command:
//     node dist/entrypoints/telemetrySender.js
//
// The hook payload is read from stdin and appended (one JSON line per
// invocation) to a dump file. argv is captured too so we can correlate
// invocations across hook events when the agent passes extra args.
// ---------------------------------------------------------------------------
import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';

function readStdin(): Promise<string> {
    return new Promise((resolve, reject) => {
        if (process.stdin.isTTY) {
            resolve('');
            return;
        }
        let buf = '';
        process.stdin.setEncoding('utf8');
        process.stdin.on('data', (chunk) => {
            buf += chunk;
        });
        process.stdin.on('end', () => resolve(buf));
        process.stdin.on('error', reject);
    });
}

async function main(): Promise<void> {
    const stdin = await readStdin();

    // Try to parse stdin as JSON so the dump is browsable; fall back to
    // raw text.
    let parsed: unknown = null;
    let parseError: string | undefined;
    try {
        parsed = stdin.length > 0 ? JSON.parse(stdin) : null;
    } catch (err) {
        parseError = err instanceof Error ? err.message : String(err);
    }

    const record = {
        ts: new Date().toISOString(),
        pid: process.pid,
        cwd: process.cwd(),
        argv: process.argv.slice(2),
        env: {
            CLAUDE_CODE_SESSION_ID: process.env.CLAUDE_CODE_SESSION_ID,
            COPILOT_SESSION_ID: process.env.COPILOT_SESSION_ID,
            VSCODE_SESSION_ID: process.env.VSCODE_SESSION_ID,
        },
        stdinLen: stdin.length,
        stdinRaw: stdin,
        stdinJson: parsed,
        parseError,
    };

    const dumpDir =
        process.env.TELEMETRY_SENDER_DEBUG_DIR ||
        path.join(os.tmpdir(), 'telemetry-sender-debug');
    fs.mkdirSync(dumpDir, { recursive: true });
    const dumpFile = path.join(dumpDir, 'hook-stdin.log');
    fs.appendFileSync(dumpFile, JSON.stringify(record) + '\n', 'utf8');

    // Echo to stderr so it doesn't pollute the agent's tool channel but
    // is still visible if the hook output is being watched.
    process.stderr.write(
        `[telemetrySender debug] wrote ${stdin.length} bytes of stdin to ${dumpFile}\n`,
    );
}

main()
    .then(() => process.exit(0))
    .catch((error: Error) => {
        process.stderr.write(`Failed: ${error.message}\n`);
        process.exit(1);
    });

