        const suffix = appBags.length > 1 ? ` across ${appBags.length} modules` : '';
        process.stdout.write(`Sent telemetry event '${eventName}'${suffix}.\n`);
    }
}

// ---------------------------------------------------------------------------
// Subcommand: session-begin
// ---------------------------------------------------------------------------

const SESSION_BEGIN_EVENT_NAME = 'modernization/session/begin';

async function runSessionBegin(ctx: CliContext): Promise<void> {
    const sessionTask = ctx.parsedArgs['task'];
