const HOOK_EVENT_NAMES = [
    'PreToolUse',
    'PostToolUse',
    'UserPromptSubmit',
    'Notification',
    'Stop',
    'SubagentStop',
    'SessionStart',
    'SessionEnd',
    'PreCompact',
] as const;
type HookEventName = (typeof HOOK_EVENT_NAMES)[number];

interface HookPayload {
    /** Hook lifecycle event name from `hook_event_name`. */
    hookEvent?: string;
    /** Agent session id (`session_id` / `sessionId`). */
    sessionId?: string;
    /** Workspace path (`cwd`). */
    cwd?: string;
