// ---------------------------------------------------------------------------
// Subcommand: send
//
// Dispatch by `hook_event_name` from stdin (Claude Code hook lifecycle).
// Each case is a placeholder: it selects the telemetry event name and may
// surface per-event properties. Extra mapping (e.g. extracting fields from
// tool_input / tool_response) can be filled in per branch later without
// touching the dispatch shape.
//
// When stdin has no `hook_event_name`, the caller must pass --eventName to
// drive the emission (non-hook usage).
// ---------------------------------------------------------------------------

function isKnownHookEvent(name: string | undefined): name is HookEventName {
    return !!name && (HOOK_EVENT_NAMES as readonly string[]).includes(name);
}

interface ResolvedSendEvent {
    eventName: string;
    extraProperties: Record<string, string>;
}

function resolveHookSendEvent(hook: HookPayload, override: string | undefined): ResolvedSendEvent {
    if (!isKnownHookEvent(hook.hookEvent)) {
        if (!override) {
            const detail = hook.hookEvent
                ? `Unknown hook_event_name '${hook.hookEvent}'.`
                : `Stdin has no 'hook_event_name'.`;
            throw new Error(`${detail} Pass --eventName <name> to override.`);
        }
        return { eventName: override, extraProperties: {} };
    }

    // Each case below is a placeholder. The event name is the only thing
    // wired up today; per-event property extraction (e.g. classifying a
    // notification, redacting prompts, surfacing PreCompact triggers) goes
    // here when the spec is finalized.
    switch (hook.hookEvent) {
        case 'PreToolUse': {
            // TODO: surface a safe subset of tool_input as properties.
            return { eventName: override ?? 'hook/preToolUse', extraProperties: {} };
        }
        case 'PostToolUse': {
            // TODO: surface a safe subset of tool_response beyond `success`.
            return { eventName: override ?? 'hook/postToolUse', extraProperties: {} };
        }
        case 'UserPromptSubmit': {
            // TODO: surface promptLength / promptHash, not the prompt body.
            return { eventName: override ?? 'hook/userPromptSubmit', extraProperties: {} };
        }
        case 'Notification': {
            // TODO: classify notification kind from message content.
            return { eventName: override ?? 'hook/notification', extraProperties: {} };
        }
        case 'Stop': {
            return { eventName: override ?? 'hook/stop', extraProperties: {} };
        }
        case 'SubagentStop': {
            return { eventName: override ?? 'hook/subagentStop', extraProperties: {} };
        }
        case 'SessionStart': {
            // TODO: include `source` (startup / resume / clear / compact).
            return { eventName: override ?? 'hook/sessionStart', extraProperties: {} };
        }
        case 'SessionEnd': {
            // TODO: include `reason`.
            return { eventName: override ?? 'hook/sessionEnd', extraProperties: {} };
        }
