498	// Subcommand: session-begin
499	// ---------------------------------------------------------------------------
500	
501	const SESSION_BEGIN_EVENT_NAME = 'modernization/session/begin';
502	
503	async function runSessionBegin(ctx: CliContext): Promise<void> {
504	    const sessionTask = ctx.parsedArgs['task'];
505	    if (!sessionTask) {
506	        throw new Error(`--task <task> is required for 'session-begin'.`);
507	    }
508	    const startedAt = new Date().toISOString();
509	
510	    const appBags = detectModuleAppBags(ctx);
511	    for (const appBag of appBags) {
512	        await sendEvent(ctx, SESSION_BEGIN_EVENT_NAME, {
513	            ...stringifyProps(appBag),
514	            sessionTask,
515	            startedAt,
516	        });
517	    }
518	
519	    if (!ctx.useStdio) {
520	        const suffix = appBags.length > 1 ? ` across ${appBags.length} modules` : '';
521	        process.stdout.write(`Started ${sessionTask} session${suffix}.\n`);
522	    }
523	}
524	
525	// ---------------------------------------------------------------------------
526	// Dispatch
527	// ---------------------------------------------------------------------------
528	
529	async function main(): Promise<void> {
530	    const { subcommand } = getSubcommand();
531	    const parsedArgs = parseArgs();
532	    const hook = parseHookPayload(await readStdin());
533	
534	    // Stdin fills in fields the caller did not pass explicitly. CLI flags
535	    // always win.
536	    if (!parsedArgs['sessionId'] && hook.sessionId) {
537	        parsedArgs['sessionId'] = hook.sessionId;
538	    }
539	    if (!parsedArgs['workspacePath'] && hook.cwd) {
540	        parsedArgs['workspacePath'] = hook.cwd;
541	    }
542	
543	    // Auto-derived hook properties — lowest precedence, can be overridden
544	    // by both stdin.properties and CLI globals.
545	    const stdinProperties: Record<string, string> = {};
546	    if (hook.tool) {
547	        stdinProperties.tool = hook.tool;
548	    }
549	    if (hook.success !== undefined) {
550	        stdinProperties.success = hook.success;
551	    }
552	    for (const [k, v] of Object.entries(hook.properties)) {
553	        stdinProperties[k] = v;
554	    }
555	
556	    const globalProperties: Record<string, string> = {};
557	    for (const [key, value] of Object.entries(parsedArgs)) {
558	        if (RESERVED_ARG_KEYS.has(key)) {
559	            continue;
560	        }
561	        globalProperties[key] = value;
562	    }
563	
564	    const settings = Settings.fromEnv();
565	    settings.loggerType = 'console';
566	    settings.serveFrom = '';
567	
568	    if (parsedArgs['callerSessionId']) {
569	        settings.callerSessionId = parsedArgs['callerSessionId'];
570	    }
571	    if (parsedArgs['sessionId']) {
572	        globalProperties['correlationId'] = parsedArgs['sessionId'];
573	    }
574	
575	    initContainer(settings);
576	
577	    const useStdio = parsedArgs['stdio'] !== undefined;
578	    if (useStdio) {
579	        container.register<ITelemetryReporter>(Beans.TelemetryReporter, {
580	            useValue: new StdoutTelemetryReporter(),
581	        });
582	    }
583	
584	    const telemetryService = container.resolve<ITelemetryService>(Beans.TelemetryService);
585	    const ctx: CliContext = {
586	        subcommand,
587	        parsedArgs,
588	        globalProperties,
589	        stdinProperties,
590	        stdinMeasurements: hook.measurements,
591	        settings,
592	        telemetryService,
593	        useStdio,
594	        workspacePath: parsedArgs['workspacePath'] || process.cwd(),
595	    };
596	
597	    switch (subcommand) {
598	        case 'send':
599	            await runSend(ctx, hook);
600	            break;
601	        case 'session-begin':
602	            await runSessionBegin(ctx);
603	            break;
604	        default: {
605	            const _exhaustive: never = subcommand;
606	            throw new Error(`Unhandled subcommand: ${_exhaustive as string}`);
607	        }
608	    }
609	
610	    if (!useStdio && container.isRegistered(Beans.TelemetryReporter)) {
611	        const reporter = container.resolve(Beans.TelemetryReporter);
612	        if (reporter instanceof ApplicationInsightsTelemetryReporter) {
613	            await reporter.flush();
614	        }
615	    }
616	}
617	
618	main()
619	    .then(() => process.exit(0))
620	    .catch((error: Error) => {
621	        process.stderr.write(`Failed: ${error.message}\n`);
622	        process.exit(1);
623	    });
