/**
 * Standalone CLI entrypoint that drives the same `TelemetryService` +
 * reporter stack used by the MCP server.
 *
 * The CLI reads a JSON **hook payload** from stdin by default. The payload
 * is the raw JSON that an agent runtime (Claude Code, Copilot CLI, ...)
 * feeds to its hook scripts. Recognised top-level fields are mapped to CLI
 * semantics; everything else is ignored.
 *
 * Hook payload schema (all fields optional):
 *
 *   {
 *     "session_id":    string,                  // → --sessionId (correlationId)
 *     "sessionId":     string,                  // alias of session_id
 *     "cwd":           string,                  // → --workspacePath default
 *     "tool_name":     string,                  // → properties.tool
 *     "toolName":      string,                  // alias of tool_name
 *     "tool_response": { "success": boolean },  // → properties.success
 *     "toolResponse":  { "success": boolean },  // alias of tool_response
 *     "properties":    Record<string, unknown>, // merged into event properties
 *     "measurements":  Record<string, number>   // merged into event measurements
 *   }
 *
 * If stdin is a TTY, empty, or invalid JSON, the run still proceeds with
 * just the CLI flags — hook scripts must never abort the agent.
 *
 * Subcommands:
 *   send            Send a single telemetry event. Requires --eventName.
 *   session-begin   Mark the beginning of a session. Emits a fixed
 *                   `modernization/session/begin` event per detected
 *                   module under --workspacePath. Requires --task.
 *
 * Global flags (apply to every subcommand):
 *   --stdio               Print events to stdout as single-line JSON
 *                         instead of sending to Application Insights.
 *   --disableTelemetry    Forwarded to Settings; suppresses sends.
 *   --callerId <id>       Name of the IDE plugin / extension invoking the
 *                         CLI.
 *   --callerType <type>   Kind of IDE host (e.g. `vscode-extension`).
 *   --callerVersion <v>   Version of that plugin / extension.
 *   --callerSessionId <id>
 *                         IDE-level session id. Back-compat dimension; NOT
 *                         promoted to AppInsights operation tags.
 *   --sessionId <id>      Agent session id; overrides stdin
 *                         `session_id`/`sessionId`. Injected as the
 *                         `correlationId` property, promoted by AppInsights
 *                         to the `operation_ParentId` tag.
 *   --workspacePath <p>   Workspace root scanned for modules. Overrides
 *                         stdin `cwd`. Defaults to process.cwd().
 *
 *   Any other `--key value` pair becomes a fixed string property merged
 *   into every event. CLI globals take precedence over stdin-derived
 *   properties.
 *
 * Subcommand-specific flags:
 *   send: --eventName <name>   Required. Telemetry event name.
 *   send: --module-level       Fan the event out per detected module.
 *   session-begin: --task <t>  Required. Free-form session task name.
 */

import 'reflect-metadata';

import { container } from 'tsyringe';

import { initContainer } from '../ioc';
import { Settings } from '../settings';
import { buildAppMetadataParser } from '../telemetry/appMetadata';
import { emptyApp, withApp } from '../telemetry/event';
import {
    ApplicationInsightsTelemetryReporter,
    ITelemetryReporter,
    ITelemetryService,
    McpPropertyMap,
    StdoutTelemetryReporter,
} from '../telemetry/telemetry';
import { Beans } from '../types';
import { parseArgs, ParsedArgs } from '../utils';

const SUBCOMMANDS = ['send', 'session-begin'] as const;
type Subcommand = (typeof SUBCOMMANDS)[number];

// Flags consumed by Settings, this dispatcher, or specific subcommands.
// Everything NOT in this set becomes a fixed string property merged onto
// every event.
const RESERVED_ARG_KEYS = new Set([
    'eventName',
    'task',
    'module-level',
    'workspacePath',
    'stdio',
    'disableTelemetry',
    'callerId',
    'callerType',
    'callerVersion',
    'callerSessionId',
    'sessionId',
]);

interface CliContext {
    subcommand: Subcommand;
    parsedArgs: ParsedArgs;
    /** Property bag from non-reserved `--key value` flags (CLI overrides). */
    globalProperties: Record<string, string>;
    /** Properties derived from stdin (lower precedence than globalProperties). */
    stdinProperties: Record<string, string>;
    /** Measurements derived from stdin. */
    stdinMeasurements: Record<string, number>;
    settings: Settings;
    telemetryService: ITelemetryService;
    useStdio: boolean;
    workspacePath: string;
}

function getSubcommand(): { subcommand: Subcommand; rest: string[] } {
    const rawArgs = process.argv.slice(2);
    const first = rawArgs[0];
    if (!first || first.startsWith('--')) {
        return { subcommand: 'send', rest: rawArgs };
    }
    if (!(SUBCOMMANDS as readonly string[]).includes(first)) {
        throw new Error(`Unknown subcommand '${first}'. Supported: ${SUBCOMMANDS.join(', ')}.`);
    }
    return { subcommand: first as Subcommand, rest: rawArgs.slice(1) };
}

// ---------------------------------------------------------------------------
// Stdin parsing
// ---------------------------------------------------------------------------

/**
 * Hook event names emitted by GitHub Copilot Chat (VS Code) and Copilot CLI.
 * Unknown values flow through `resolveHookSendEvent`'s fallback and require
 * `--eventName` to override.
 */
const HOOK_EVENT_NAMES = [
    'SessionStart',
    'UserPromptSubmit',
    'PreToolUse',
    'PostToolUse',
    'PreCompact',
    'SubagentStart',
    'SubagentStop',
    'Stop',
] as const;
type HookEventName = (typeof HOOK_EVENT_NAMES)[number];

interface HookPayload {
    /** Hook lifecycle event name from `hookEventName` / `hook_event_name`. */
    hookEvent?: string;
    /** Agent session id (`sessionId` / `session_id`). */
    sessionId?: string;
    /** Workspace path (`cwd`). */
    cwd?: string;
    /** ISO 8601 timestamp from the hook payload. */
    timestamp?: string;
    /** Path to the conversation transcript on disk (`transcript_path`). */
    transcriptPath?: string;
    /** Tool name (`tool_name` / `toolName`). */
    tool?: string;
    /** Raw tool input object (`tool_input`). */
    toolInput?: Record<string, unknown>;
    /**
     * Raw tool response from `tool_response` / `toolResponse`.
     * Copilot Chat emits a string; some payloads emit an object — keep both.
     */
    toolResponse?: string | Record<string, unknown>;
    /** Unique identifier for a tool call (`tool_use_id`). */
    toolUseId?: string;
    /** Derived from `tool_response.success` when tool_response is an object. */
    success?: string;
    /** UserPromptSubmit body. */
    prompt?: string;
    /** SessionStart source (e.g. `new`). */
    source?: string;
    /** PreCompact trigger (e.g. `auto`). */
    trigger?: string;
    /** Subagent identifier (`agent_id`). */
    agentId?: string;
    /** Subagent type / role (`agent_type`). */
    agentType?: string;
    /** Stop / SubagentStop reentry guard. */
    stopHookActive?: string;
    /** Caller-supplied extra properties merged onto the event. */
    properties: Record<string, string>;
    /** Caller-supplied measurements merged onto the event. */
    measurements: Record<string, number>;
}

function readStdin(): Promise<string> {
    return new Promise((resolve, reject) => {
        if (process.stdin.isTTY) {
            resolve('');
            return;
        }
        let buf = '';
        process.stdin.setEncoding('utf8');
        process.stdin.on('data', (chunk) => {
            buf += chunk;
        });
        process.stdin.on('end', () => resolve(buf));
        process.stdin.on('error', reject);
    });
}

function pickString(obj: Record<string, unknown>, ...keys: string[]): string | undefined {
    for (const k of keys) {
        const v = obj[k];
        if (typeof v === 'string' && v.length > 0) {
            return v;
        }
    }
    return undefined;
}

function pickNested(
    obj: Record<string, unknown>,
    parents: string[],
    leaf: string,
): unknown | undefined {
    for (const p of parents) {
        const parent = obj[p];
        if (parent && typeof parent === 'object' && !Array.isArray(parent)) {
            const v = (parent as Record<string, unknown>)[leaf];
            if (v !== undefined && v !== null) {
                return v;
            }
        }
    }
    return undefined;
}

function toStringProps(input: unknown): Record<string, string> {
    if (!input || typeof input !== 'object' || Array.isArray(input)) {
        return {};
    }
    const out: Record<string, string> = {};
    for (const [k, v] of Object.entries(input as Record<string, unknown>)) {
        if (v === undefined || v === null) {
            continue;
        }
        out[k] = typeof v === 'string' ? v : JSON.stringify(v);
    }
    return out;
}

function toNumberMeasurements(input: unknown): Record<string, number> {
    if (!input || typeof input !== 'object' || Array.isArray(input)) {
        return {};
    }
    const out: Record<string, number> = {};
    for (const [k, v] of Object.entries(input as Record<string, unknown>)) {
        if (typeof v === 'number' && Number.isFinite(v)) {
            out[k] = v;
        }
    }
    return out;
}

function pickObject(
    obj: Record<string, unknown>,
    ...keys: string[]
): Record<string, unknown> | undefined {
    for (const k of keys) {
        const v = obj[k];
        if (v && typeof v === 'object' && !Array.isArray(v)) {
            return v as Record<string, unknown>;
        }
    }
    return undefined;
}

/**
 * Best-effort: a malformed / empty / non-JSON stdin produces an empty
 * payload, never an error. Hooks must not abort the agent.
 */
function parseHookPayload(raw: string): HookPayload {
    const empty: HookPayload = { properties: {}, measurements: {} };
    if (!raw || raw.trim().length === 0) {
        return empty;
    }
    let parsed: unknown;
    try {
        parsed = JSON.parse(raw);
    } catch {
        return empty;
    }
    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
        return empty;
    }
    const obj = parsed as Record<string, unknown>;

    const successRaw = pickNested(obj, ['tool_response', 'toolResponse'], 'success');
    const success = successRaw === undefined ? undefined : String(successRaw);

    // tool_response is a string in Copilot Chat, but other runtimes / future
    // versions may switch to an object. Accept both shapes.
    const toolResponseRaw = obj['tool_response'] ?? obj['toolResponse'];
    let toolResponse: string | Record<string, unknown> | undefined;
    if (typeof toolResponseRaw === 'string') {
        toolResponse = toolResponseRaw;
    } else if (
        toolResponseRaw &&
        typeof toolResponseRaw === 'object' &&
        !Array.isArray(toolResponseRaw)
    ) {
        toolResponse = toolResponseRaw as Record<string, unknown>;
    }

    return {
        hookEvent: pickString(obj, 'hookEventName', 'hook_event_name'),
        sessionId: pickString(obj, 'sessionId', 'session_id'),
        cwd: pickString(obj, 'cwd'),
        timestamp: pickString(obj, 'timestamp'),
        transcriptPath: pickString(obj, 'transcript_path', 'transcriptPath'),
        tool: pickString(obj, 'tool_name', 'toolName'),
        toolInput: pickObject(obj, 'tool_input', 'toolInput'),
        toolResponse,
        toolUseId: pickString(obj, 'tool_use_id', 'toolUseId'),
        success,
        prompt: pickString(obj, 'prompt'),
        source: pickString(obj, 'source'),
        trigger: pickString(obj, 'trigger'),
        agentId: pickString(obj, 'agent_id', 'agentId'),
        agentType: pickString(obj, 'agent_type', 'agentType'),
        stopHookActive: (() => {
            const v = obj['stop_hook_active'] ?? obj['stopHookActive'];
            return v === undefined || v === null ? undefined : String(v);
        })(),
        properties: toStringProps(obj.properties),
        measurements: toNumberMeasurements(obj.measurements),
    };
}

// ---------------------------------------------------------------------------
// Event emission
// ---------------------------------------------------------------------------

async function sendEvent(
    ctx: CliContext,
    eventName: string,
    extraProperties: Record<string, string> = {},
    measurements: Record<string, number> = {},
): Promise<void> {
    // Precedence (low → high):
    //   1. auto-derived hook context (tool, success)
    //   2. stdin.properties
    //   3. caller-supplied extras (per-call: app bag, sessionTask, ...)
    //   4. CLI globals (--key value)
    const properties: Record<string, string> = {
        ...ctx.stdinProperties,
        ...extraProperties,
        ...ctx.globalProperties,
    };
    const mergedMeasurements: Record<string, number> = {
        ...ctx.stdinMeasurements,
        ...measurements,
    };
    await ctx.telemetryService.sendTelemetryEvent(
        eventName as keyof McpPropertyMap,
        properties as McpPropertyMap[keyof McpPropertyMap]['properties'],
        mergedMeasurements as McpPropertyMap[keyof McpPropertyMap]['measurements'],
    );
}

function detectModuleAppBags(ctx: CliContext): Record<string, unknown>[] {
    const metadatas = buildAppMetadataParser(ctx.workspacePath).findAppMetadatas();
    if (metadatas.length === 0) {
        return [emptyApp() as unknown as Record<string, unknown>];
    }
    return metadatas.map((m) => withApp(m) as unknown as Record<string, unknown>);
}

function stringifyProps(props: Record<string, unknown>): Record<string, string> {
    const result: Record<string, string> = {};
    for (const [k, v] of Object.entries(props)) {
        if (v === undefined || v === null) {
            continue;
        }
        result[k] = typeof v === 'string' ? v : JSON.stringify(v);
    }
    return result;
}

// ---------------------------------------------------------------------------
// Subcommand: send
//
// Dispatch by `hook_event_name` from stdin (Claude Code hook lifecycle).
// Each case is a placeholder: it selects the telemetry event name and may
// surface per-event properties. Extra mapping (e.g. extracting fields from
// tool_input / tool_response) can be filled in per branch later without
// touching the dispatch shape.
//
// When stdin has no `hook_event_name`, the caller must pass --eventName to
// drive the emission (non-hook usage).
// ---------------------------------------------------------------------------

function isKnownHookEvent(name: string | undefined): name is HookEventName {
    return !!name && (HOOK_EVENT_NAMES as readonly string[]).includes(name);
}

interface ResolvedSendEvent {
    eventName: string;
    extraProperties: Record<string, string>;
}

/**
 * Resolve the telemetry event for a `send` invocation.
 *
 * Returns `null` when the case is deliberately a no-op — the hook event is
 * recognised but we don't want telemetry for it. Throws when stdin has no
 * usable `hookEventName` and the caller did not pass `--eventName`.
 *
 * Each switch arm picks the telemetry event name and may surface per-event
 * properties; complex field extraction (tool_input subset, agent_id, ...)
 * goes here when the spec is finalized.
 */
function resolveHookSendEvent(
    hook: HookPayload,
    override: string | undefined,
): ResolvedSendEvent | null {
    if (!isKnownHookEvent(hook.hookEvent)) {
        if (!override) {
            const detail = hook.hookEvent
                ? `Unknown hookEventName '${hook.hookEvent}'.`
                : `Stdin has no 'hookEventName'.`;
            throw new Error(`${detail} Pass --eventName <name> to override.`);
        }
        return { eventName: override, extraProperties: {} };
    }

    // An explicit --eventName always wins, even for cases that would
    // otherwise be skipped — that's how callers ad-hoc surface a hook
    // event we don't normally track.
    if (override) {
        return { eventName: override, extraProperties: {} };
    }

    switch (hook.hookEvent) {
        case 'SessionStart': {
            // TODO: include `source` (currently always "new" in Copilot Chat).
            return { eventName: 'hook/sessionStart', extraProperties: {} };
        }
        case 'UserPromptSubmit': {
            // TODO: surface promptLength / promptHash, not the prompt body.
            return { eventName: 'hook/userPromptSubmit', extraProperties: {} };
        }
        case 'PreToolUse': {
            // TODO: surface a safe subset of tool_input as properties.
            return { eventName: 'hook/preToolUse', extraProperties: {} };
        }
        case 'PostToolUse': {
            // TODO: surface tool_response shape (string length, parsed
            // success/error, ...).
            return { eventName: 'hook/postToolUse', extraProperties: {} };
        }
        case 'PreCompact': {
            // TODO: include `trigger` (currently `auto` in Copilot Chat).
            return { eventName: 'hook/preCompact', extraProperties: {} };
        }
        case 'SubagentStart': {
            // TODO: include `agent_id` / `agent_type`.
            return { eventName: 'hook/subagentStart', extraProperties: {} };
        }
        case 'SubagentStop': {
            // TODO: include `agent_id` / `agent_type`.
            return { eventName: 'hook/subagentStop', extraProperties: {} };
        }
        case 'Stop': {
            return { eventName: 'hook/stop', extraProperties: {} };
        }
        default: {
            const _exhaustive: never = hook.hookEvent;
            throw new Error(`Unhandled hook event: ${_exhaustive as string}`);
        }
    }
}

async function runSend(ctx: CliContext, hook: HookPayload): Promise<void> {
    const resolved = resolveHookSendEvent(hook, ctx.parsedArgs['eventName']);
    if (resolved === null) {
        if (!ctx.useStdio) {
            process.stdout.write(`Skipped telemetry for hook event '${hook.hookEvent}'.\n`);
        }
        return;
    }
    const { eventName, extraProperties } = resolved;
    const appBags = ctx.parsedArgs['module-level'] === undefined ? [{}] : detectModuleAppBags(ctx);
    for (const appBag of appBags) {
        await sendEvent(ctx, eventName, { ...extraProperties, ...stringifyProps(appBag) });
    }
    if (!ctx.useStdio) {
        const suffix = appBags.length > 1 ? ` across ${appBags.length} modules` : '';
        process.stdout.write(`Sent telemetry event '${eventName}'${suffix}.\n`);
    }
}

// ---------------------------------------------------------------------------
// Subcommand: session-begin
// ---------------------------------------------------------------------------

const SESSION_BEGIN_EVENT_NAME = 'modernization/session/begin';

async function runSessionBegin(ctx: CliContext): Promise<void> {
    const sessionTask = ctx.parsedArgs['task'];
    if (!sessionTask) {
        throw new Error(`--task <task> is required for 'session-begin'.`);
    }
    const startedAt = new Date().toISOString();

    const appBags = detectModuleAppBags(ctx);
    for (const appBag of appBags) {
        await sendEvent(ctx, SESSION_BEGIN_EVENT_NAME, {
            ...stringifyProps(appBag),
            sessionTask,
            startedAt,
        });
    }

    if (!ctx.useStdio) {
        const suffix = appBags.length > 1 ? ` across ${appBags.length} modules` : '';
        process.stdout.write(`Started ${sessionTask} session${suffix}.\n`);
    }
}

// ---------------------------------------------------------------------------
// Dispatch
// ---------------------------------------------------------------------------

async function main(): Promise<void> {
    const { subcommand } = getSubcommand();
    const parsedArgs = parseArgs();
    const hook = parseHookPayload(await readStdin());

    // Stdin fills in fields the caller did not pass explicitly. CLI flags
    // always win.
    if (!parsedArgs['sessionId'] && hook.sessionId) {
        parsedArgs['sessionId'] = hook.sessionId;
    }
    if (!parsedArgs['workspacePath'] && hook.cwd) {
        parsedArgs['workspacePath'] = hook.cwd;
    }

    // Auto-derived hook properties — lowest precedence, can be overridden
    // by both stdin.properties and CLI globals.
    const stdinProperties: Record<string, string> = {};
    if (hook.tool) {
        stdinProperties.tool = hook.tool;
    }
    if (hook.success !== undefined) {
        stdinProperties.success = hook.success;
    }
    for (const [k, v] of Object.entries(hook.properties)) {
        stdinProperties[k] = v;
    }

    const globalProperties: Record<string, string> = {};
    for (const [key, value] of Object.entries(parsedArgs)) {
        if (RESERVED_ARG_KEYS.has(key)) {
            continue;
        }
        globalProperties[key] = value;
    }

    const settings = Settings.fromEnv();
    settings.loggerType = 'console';
    settings.serveFrom = '';

    if (parsedArgs['callerSessionId']) {
        settings.callerSessionId = parsedArgs['callerSessionId'];
    }
    if (parsedArgs['sessionId']) {
        globalProperties['correlationId'] = parsedArgs['sessionId'];
    }

    initContainer(settings);

    const useStdio = parsedArgs['stdio'] !== undefined;
    if (useStdio) {
        container.register<ITelemetryReporter>(Beans.TelemetryReporter, {
            useValue: new StdoutTelemetryReporter(),
        });
    }

    const telemetryService = container.resolve<ITelemetryService>(Beans.TelemetryService);
    const ctx: CliContext = {
        subcommand,
        parsedArgs,
        globalProperties,
        stdinProperties,
        stdinMeasurements: hook.measurements,
        settings,
        telemetryService,
        useStdio,
        workspacePath: parsedArgs['workspacePath'] || process.cwd(),
    };

    switch (subcommand) {
        case 'send':
            await runSend(ctx, hook);
            break;
        case 'session-begin':
            await runSessionBegin(ctx);
            break;
        default: {
            const _exhaustive: never = subcommand;
            throw new Error(`Unhandled subcommand: ${_exhaustive as string}`);
        }
    }

    if (!useStdio && container.isRegistered(Beans.TelemetryReporter)) {
        const reporter = container.resolve(Beans.TelemetryReporter);
        if (reporter instanceof ApplicationInsightsTelemetryReporter) {
